package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a waiver by anyone but a steward. */
public class ValidateWaive {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody WaiveRequest request, Out<WaiveInput> body,
            RoleStore roles) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        if (roles.find(sheetId.trim(), user) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward can waive a late charge");
        }
        body.set(new WaiveInput(user));
    }
}
package net.officefloor.hq.app.claim;

/** Body of a claim's late charge waiver, as sent: who waives it. */
public record WaiveRequest(String user) {
}
package net.officefloor.hq.app.claim;

/** A validated late charge waiver: the steward who waives it. */
public record WaiveInput(String user) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Refuses waiving a claim that is not OPEN or PENDING, or one already waived. */
public class CheckWaive {
    public void check(@Val Claim claim) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim can have its late charge waived");
        }
        if (claim.isWaived()) {
            throw new InvalidSheetException("The claim's late charge is already waived");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Stores the claim's late charge waived; refused when another user moved it on or waived it first. */
public class ApplyWaive {
    public void apply(@Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (!store.waive(claim)) {
            throw new InvalidSheetException("Only an OPEN or PENDING claim not yet waived can have its late charge waived");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.plugin.variable.Val;

/** Records a stored waiver: CLAIM_WAIVED sheet=<id> by=<user> person=<name> amount=<0.00> date=<yyyy-mm-dd>,
 *  then number=<n> when the claim has one; then how it moved the sheet's figures. */
public class AuditClaimWaived {
    public void audit(@Val WaiveInput input, @Val Claim claim, @Val Rollup before, PersonStore people, Audit audit,
            RollupService rollups) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_WAIVED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber()));
        rollups.record(claim.getSheetId(), input.user(), before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("claimId") String claimId,
            ClaimStore store, Out<Claim> claimOut) throws InvalidSheetException {
        Claim claim = null;
        try {
            claim = store.find(sheetId.trim(), Long.parseLong(claimId.trim()));
        } catch (NumberFormatException e) {
            // not an id: no such claim
        }
        if (claim == null) {
            throw new InvalidSheetException("No such claim: " + claimId);
        }
        claimOut.set(claim);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetStore;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, ClaimStore store, ClaimLogStore log, ClaimCommentStore comments, ClaimLineStore lines, SheetStore sheets, ObjectResponse<ClaimResponse> response) {
        Claim corrected = claim.getCorrects() == null ? null
                : store.findByNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
        response.send(ClaimResponse.from(claim, corrected == null ? claim.getDate() : corrected.getDate()).withLog(log.lines(claim))
                .withComments(comments.lines(claim)).withLines(lines.lines(claim))
                .on(sheets.today(claim.getSheetId())));
    }
}

