package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses a review assignment by anyone but a steward, or to a blank user. */
public class ValidateAssignReview {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody AssignReviewRequest request,
            Out<AssignReviewInput> body, RoleStore roles) throws InvalidSheetException {
        String user = request == null || request.user() == null ? "" : request.user().trim();
        roles.refuseChange(sheetId.trim(), user);
        if (roles.find(sheetId.trim(), user) != Role.STEWARD) {
            throw new InvalidSheetException("Only a steward can assign a review");
        }
        String assignee = request.assignee() == null ? "" : request.assignee().trim();
        if (assignee.isEmpty()) {
            throw new InvalidSheetException("A review must be assigned to a user");
        }
        body.set(new AssignReviewInput(user, assignee));
    }
}
EOF
cat > ApplyAssignReview.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Val;

/** Stores the claim's review assigned to the user; refused when the claim is not (or no longer) in REVIEW. */
public class ApplyAssignReview {
    public void apply(@Val AssignReviewInput input, @Val Claim claim, ClaimStore store) throws InvalidSheetException {
        if (claim.getStatus() != ClaimStatus.REVIEW || !store.assignReview(claim, input.assignee())) {
            throw new InvalidSheetException("Only a REVIEW claim can have its review assigned");
        }
    }
}
EOF
cat > AuditReviewAssigned.java <<'EOF'
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.plugin.variable.Val;

/** Records a stored review assignment: REVIEW_ASSIGNED sheet=<id> by=<user> person=<name> amount=<0.00>
 *  date=<yyyy-mm-dd> user=<assignee>. */
public class AuditReviewAssigned {
    public void audit(@Val AssignReviewInput input, @Val Claim claim, PersonStore people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("REVIEW_ASSIGNED sheet=" + claim.getSheetId() + " by=" + input.user() + " person="
                + person.getName() + " amount=" + shown.amount() + " date=" + shown.date()
                + " user=" + input.assignee());
    }
}
EOF
